// it is written; `dokimos verification coverage` reports DOKIMOS-UNIMPLEMENTED as a placeholder.
namespace Evidence.Tests

open System
open System.Collections.Concurrent
open System.IO
open System.Net
open System.Net.Http
open System.Net.Sockets
open System.Threading.Tasks
open Xunit
open Evidence

module EVD005Tests =
    type private Recorded =
        { Path: string
          Query: string
          RawUrl: string
          Headers: (string * string) list }

    type private Provider =
        { BaseUrl: string
          Requests: unit -> Recorded list
          Stop: unit -> unit }

    let private freePort () =
        let l = TcpListener(IPAddress.Loopback, 0)
        l.Start()
        let port = (l.LocalEndpoint :?> IPEndPoint).Port
        l.Stop()
        port

    let private record (req: HttpListenerRequest) =
        { Path = req.Url.AbsolutePath
          Query = req.Url.Query
          RawUrl = req.RawUrl
          Headers =
            req.Headers.AllKeys
            |> Array.map (fun k -> k, req.Headers.[k])
            |> Array.toList }

    /// Starts a real HTTP provider on 127.0.0.1; `respond` maps the request path to (status, body).
    let private startProvider (respond: string -> int * byte[]) : Provider =
        let port = freePort ()
        let listener = new HttpListener()
        listener.Prefixes.Add(sprintf "http://127.0.0.1:%d/" port)
        listener.Start()
        let log = ConcurrentQueue<Recorded>()
        let handle (ctx: HttpListenerContext) =
            try
                log.Enqueue(record ctx.Request)
                let status, body = respond ctx.Request.Url.AbsolutePath
                ctx.Response.StatusCode <- status
                ctx.Response.ContentType <- "application/octet-stream"
                ctx.Response.ContentLength64 <- int64 body.Length
                ctx.Response.OutputStream.Write(body, 0, body.Length)
                ctx.Response.OutputStream.Close()
            with _ -> (try ctx.Response.Abort() with _ -> ())
        let rec loop () =
            match (try Some(listener.GetContext()) with _ -> None) with
            | Some ctx ->
                handle ctx
                loop ()
            | None -> ()
        Task.Run(fun () -> loop ()) |> ignore
        { BaseUrl = sprintf "http://127.0.0.1:%d" port
          Requests = fun () -> log.ToArray() |> Array.toList
          Stop = fun () -> (try listener.Stop(); listener.Close() with _ -> ()) }

    let private withProvider (respond: string -> int * byte[]) (f: Provider -> unit) =
        let provider = startProvider respond
        try f provider
        finally provider.Stop()

    let private run (t: Task<'a>) = t.GetAwaiter().GetResult()

    let private token = "tok-EVD005-SECRET-9b2f71e04c"

    let rec private messages (ex: exn) : string list =
        match ex with
        | null -> []
        | :? AggregateException as agg ->
            ex.Message :: (agg.InnerExceptions |> Seq.toList |> List.collect messages)
        | _ -> ex.Message :: ex.ToString() :: messages ex.InnerException

    /// Runs a call and returns either its result or the messages of the exception it raised.
    let private attempt (f: unit -> Task<Result<'a, EvidenceError>>) : Choice<Result<'a, EvidenceError>, string list> =
        try Choice1Of2(run (f ()))
        with ex -> Choice2Of2(messages ex)

    let private assertNoToken (what: string) (text: string) =
        Assert.False((text <> null && text.Contains token), sprintf "token leaked in %s: %s" what text)

    let private checkOutcome (label: string) (outcome: Choice<Result<'a, EvidenceError>, string list>) =
        match outcome with
        | Choice1Of2 (Ok _) -> failwithf "%s: expected a failure, got Ok" label
        | Choice1Of2 (Error e) ->
            assertNoToken (label + " error") (sprintf "%A" e)
            assertNoToken (label + " error") (string e)
        | Choice2Of2 msgs -> msgs |> List.iter (assertNoToken (label + " exception"))

    let private closedPortBaseUrl () = sprintf "http://127.0.0.1:%d" (freePort ())

    /// EVD-005-O1: the token's value never appears in any `ProviderError`, any exception message, or any line written to the collector's diagnostic log (`Collector.Diagnostics`), including for 401 and network failures.
    [<Fact>]
    let ``EVD-005-O1`` () : unit =
        let statusOf (path: string) =
            if path.EndsWith "-401" then 401
            elif path.EndsWith "-403" then 403
            elif path.EndsWith "-404" then 404
            elif path.EndsWith "-429" then 429
            elif path.EndsWith "-500" then 500
            else 200
        withProvider
            (fun path -> statusOf path, Text.Encoding.UTF8.GetBytes "provider says no")
            (fun provider ->
                use http = new HttpClient()
                let client = ProviderClient(http, provider.BaseUrl, token)
                let collector = Collector(client, provider.BaseUrl, "collector-sec")
                let failing = [ "x-401"; "x-403"; "x-404"; "x-429"; "x-500" ]
                failing
                |> List.iter (fun id ->
                    attempt (fun () -> client.Fetch id) |> checkOutcome ("Fetch " + id)
                    attempt (fun () -> collector.Collect id) |> checkOutcome ("Collect " + id))
                // A successful collection must not log the token either.
                match attempt (fun () -> collector.Collect "ok-1") with
                | Choice1Of2 (Ok r) ->
                    assertNoToken "record" r.Source
                    assertNoToken "record" r.CollectedBy
                | Choice1Of2 (Error e) -> failwithf "expected Ok for ok-1, got %A" e
                | Choice2Of2 msgs -> failwithf "Collect ok-1 threw: %A" msgs
                let lines = collector.Diagnostics
                Assert.NotEmpty(lines)
                lines |> List.iter (assertNoToken "diagnostics (live provider)"))

        // Network failure: a port with nothing listening.
        let deadUrl = closedPortBaseUrl ()
        use http = new HttpClient(Timeout = TimeSpan.FromSeconds 10.0)
        let client = ProviderClient(http, deadUrl, token)
        let collector = Collector(client, deadUrl, "collector-sec")
        attempt (fun () -> client.Fetch "net-1") |> checkOutcome "Fetch (network failure)"
        attempt (fun () -> collector.Collect "net-2") |> checkOutcome "Collect (network failure)"
        let lines = collector.Diagnostics
        Assert.NotEmpty(lines)
        lines |> List.iter (assertNoToken "diagnostics (network failure)")
